let basket, star;
let score = 0;

function setup() {
  new Canvas(400, 300);
  basket = new Sprite(200, 280, 80, 16);
  basket.color = 'rgb(255, 184, 108)'; // CONVERTED: shapeColor is just .color in moSHion
  basket.collider = 'none'; // CONVERTED: p5play's overlap() let the two pass through each other; here we use collider 'none' plus overlaps()
  star = new Sprite(random(20, 380), 0, 18, 18);
  star.color = 'rgb(241, 250, 140)'; // CONVERTED: shapeColor is just .color in moSHion
  star.collider = 'none'; // CONVERTED: same reason as the basket
  star.vel.y = 3; // CONVERTED: .velocity is .vel in moSHion
}

function update() {
  // CONVERTED: moving and input logic moved out of draw() into update()
  basket.x = constrain(mouse.x, 40, width - 40); // CONVERTED: position.x is .x, mouseX is mouse.x
  if (star.overlaps(basket)) { // CONVERTED: overlap() is a per-frame query called overlaps() in moSHion
    score++;
    star.y = 0; // CONVERTED: position.y is .y
    star.x = random(20, 380); // CONVERTED: position.x is .x
  }
  if (star.y > height) { // CONVERTED: position.y is .y
    star.y = 0;
    star.x = random(20, 380);
  }
}

function draw() {
  background(40, 42, 54);
  // CONVERTED: drawSprites() deleted — moSHion draws the sprites for us
}

function drawTop() {
  // CONVERTED: the score text moved to drawTop() so it shows on top of the sprites
  fill(255);
  textSize(18);
  text('Score: ' + score, 10, 24);
}
